package com.nextrade.api.security; import com.nextrade.common.identifier.*; import com.nextrade.service.JwtKeyRing; import com.nextrade.service.ports.AccessTokenIssuer; import io.jsonwebtoken.*; import java.time.*; import java.util.*; public final class AccessTokenService implements AccessTokenIssuer {private final JwtKeyRing ring;private final Duration ttl;public AccessTokenService(JwtKeyRing ring,Duration ttl){this.ring=ring;this.ttl=ttl;}@Override public String issue(UserId id,String role,SessionId session){Instant now=Instant.now();return Jwts.builder().subject(id.asString()).id(session.asString()).claim("token_type","access").claim("role",role).header().keyId(ring.activeKid()).and().issuedAt(Date.from(now)).expiration(Date.from(now.plus(ttl))).signWith(ring.active()).compact();}public Jws<Claims> parse(String token){String kid=com.nextrade.service.JwtKidResolver.resolve(token);return Jwts.parser().verifyWith(ring.key(kid)).build().parseSignedClaims(token);}}
